import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {resolve} from 'node:path';
import {pathToFileURL} from 'node:url';
import {mkdir,writeFile} from 'node:fs/promises';
const require=createRequire(import.meta.url),{chromium}=require('C:/Users/genki/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright-core');
const evidence=resolve('../../outputs/verification-v34-pitch-chart-v1');await mkdir(evidence);
const browser=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true});
try{
 const page=await browser.newPage({viewport:{width:1200,height:860}});
 await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv31_TBD_vs_LAD_剛体バット描画版.html')).href);await page.evaluate(()=>document.fonts.ready);
 await page.evaluate(()=>{const p=window.matchPreview.recording.pitches[0];window.matchPreview.seek(p.confirm);});
 const original=await page.evaluate(()=>({pixels:document.getElementById('pitch-chart').toDataURL(),legend:document.getElementById('symbol-legend').innerHTML}));
 await page.addScriptTag({path:resolve('tools/browser-bridge/live-pitch-chart.js')});
 const parity=await page.evaluate(()=>{
  const s=window.matchPreview.inspect(),f=window.matchPreview.getFrame();
  const api=window.KneekuraLivePitchChart.create({canvas:document.getElementById('pitch-chart'),caption:document.getElementById('chart-caption'),legend:document.getElementById('symbol-legend'),core:{createSourceBallMaterialHistoryV1(){throw Error('not needed for approved-entry raster parity');}}});
  api.draw({history:s.history,batterHeightMeters:f.batter.height,selectedPitchId:s.history.at(-1)?.pitchId});
  return {pixels:document.getElementById('pitch-chart').toDataURL(),legend:document.getElementById('symbol-legend').innerHTML,marks:api.inspect().chartMarks};
 });
 assert.equal(parity.pixels,original.pixels,'approved v31 chart pixels');assert.equal(parity.legend,original.legend,'approved v31 legend');
 await page.goto(pathToFileURL(resolve('../../outputs/ばせぼーるlv33_TBD_vs_LAD_Core試合版.html')).href);await page.evaluate(()=>document.fonts.ready);
 await page.addScriptTag({path:resolve('tools/browser-bridge/live-pitch-chart.js')});
 const live=await page.evaluate(()=>{
  document.getElementById('managed-team').value='0';document.getElementById('batting-choice').value='take';
  document.getElementById('next-pitch').click();window.liveMatchPlayback.stop();
  document.getElementById('next-pitch').click();window.liveMatchPlayback.stop();
  const state=window.liveMatchPlayback.inspect(),records=state.host.history,before=JSON.stringify(records),first=records[0],second=records[1];
  const chosen=[];const api=window.KneekuraLivePitchChart.create({canvas:document.getElementById('pitch-chart'),caption:document.getElementById('chart-caption'),core:window.KneekuraNativeMatchCore,onSelect:value=>chosen.push(value)});
  const height=JSON.parse(document.getElementById('match-data').textContent).players[first.batterPlayerId].height;
  const observing=(index,tick,selectedPitchId=null)=>api.observe({records,pitchIndex:index,atTick:tick,batterHeightMeters:height,selectedPitchId});
  const pre=observing(0,first.play.rules.endedAtTick-1),one=observing(0,first.play.rules.endedAtTick),future=observing(1,second.play.rules.endedAtTick-1),two=observing(1,second.play.rules.endedAtTick);
  api.draw(two);const selected=api.inspect().chartMarks.at(-1),box=document.getElementById('pitch-chart').getBoundingClientRect(),clock=state.currentFrame.tick;
  if(selected)document.getElementById('pitch-chart').dispatchEvent(new MouseEvent('click',{clientX:box.left+selected.x/320*box.width,clientY:box.top+selected.y/304*box.height,bubbles:true}));
  const actual=one.history[0],initial=first.play.diagnostics.sourceDescriptor.initial;
  return {pre:pre.history.length,one:one.history.length,future:future.history.length,two:two.history.length,numbers:two.history.map(e=>e.number),
   actual,locations:one.locations,zone:one.zone,height,inputUnchanged:JSON.stringify(records)===before,
   chosen,clockUnchanged:window.liveMatchPlayback.inspect().currentFrame.tick===clock,sourceOriginTick:initial.originTick,legacyCount:window.matchPreview.recording.pitches.length};
 });
 assert.equal(live.pre,0);assert.equal(live.one,1);assert.equal(live.future,1);assert.equal(live.two,2);assert.deepEqual(live.numbers,[1,2]);
 assert.equal(live.actual.location.kind,'plate-crossing');assert(Math.abs(live.actual.location.position.z-.15)<1e-9);assert.equal(live.locations[0].interpolated,false);assert.equal(live.locations[0].extrapolatedAfterContact,false);
 assert.equal(live.inputUnchanged,true);assert.equal(live.clockUnchanged,true);assert.equal(live.chosen.length,1);assert.equal(live.chosen[0].pitchId,'live-pitch-1');
 assert.equal(live.zone.upperY,live.height*.535);assert.equal(live.zone.lowerY,live.height*.270);
 await page.locator('#pitch-chart').screenshot({path:resolve(evidence,'core-pitch-chart.png')});
 await writeFile(resolve(evidence,'chart-check.json'),JSON.stringify({status:'PASS',approvedV31PixelsIdentical:true,approvedLegendIdentical:true,live},null,2)+'\n');
 console.log(JSON.stringify({status:'PASS',approvedV31PixelsIdentical:true,approvedLegendIdentical:true,actualPlatePosition:live.actual.location.position,nofuture:true,inputUnchanged:true,clickDoesNotMoveClock:true,evidence}));
 await page.close();
}finally{await browser.close();}
